using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming. She holds a Ph.D. in Computer Science from MIT and specializes in CS education.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright is an algorithm researcher with publications in top conferences. He received his Ph.D. from Stanford University.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Introduction to database design, SQL, normalization, transactions, and modern database technologies including NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked at Oracle for 10 years before joining academia. Her research focuses on distributed database systems.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 4, Code = "CS 450", Title = "Machine Learning", Description = "Foundational concepts in machine learning including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Alex Kumar", InstructorBio = "Dr. Kumar leads the university's AI research lab and has published extensively in NeurIPS and ICML.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Tanaka", InstructorBio = "Dr. Tanaka is an award-winning educator who has taught calculus for over 20 years.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emily Foster", InstructorBio = "Dr. Foster specializes in applied mathematics and has consulting experience with aerospace companies.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 7, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is a statistician with experience in biostatistics and clinical trials research.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Helen Zhao", InstructorBio = "Dr. Zhao is an experimental physicist who previously worked at CERN on particle detection systems.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 9, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres researches photonics and has multiple patents in optical communication systems.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 10, Code = "ENG 101", Title = "College Writing", Description = "Develop college-level writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. Linda Hayes", InstructorBio = "Prof. Hayes is a published author and writing coach with expertise in academic and creative writing.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 11, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and culture.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson is a literary scholar specializing in 20th-century American fiction and the Harlem Renaissance.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the late medieval period, covering major empires and cultural exchanges.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Patricia Okonkwo", InstructorBio = "Dr. Okonkwo is a historian specializing in cross-cultural exchanges in the ancient and medieval world.", DepartmentId = 5, IsFeatured = false },
        new() { Id = 13, Code = "HIST 205", Title = "Modern European History", Description = "European history from the Enlightenment to the present, including revolutions, world wars, and the formation of the EU.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", InstructorName = "Dr. Friedrich Weber", InstructorBio = "Dr. Weber studied at the University of Heidelberg and specializes in 19th and 20th century European political history.", DepartmentId = 5, IsFeatured = false },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";
}

